import {studyItem,canonicalId,foundationSkipped,eligible} from './engine.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sourceLink(url,label){return url&&/^https:\/\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:'';}
export function needsContextAudio(w,lib){const base=lib.words[w.wordId||canonicalId(w.id)],variants=(base?.studyItemIds||[]).map(id=>studyItem(lib,id)).filter(Boolean);return !!w.isAdditionalSense||variants.some(other=>['uk','us'].some(accent=>w.ipa?.[accent]&&other.ipa?.[accent]&&w.ipa[accent]!==other.ipa[accent]));}
export function pronunciationText(w,lib){return needsContextAudio(w,lib)?w.examples?.[0]?.text||w.example||w.word:w.word;}
function partHTML(p,lib,w){const action=p.wordId&&lib.words[p.wordId]?`data-word="${esc(p.wordId)}"`:p.key&&lib.cards[p.key]?`data-card="${esc(p.key)}"`:`data-part="${esc(p.text)}" data-context="${esc(w.id)}"`;return`<${action?'button':'span'} class="morph-unit ${p.role==='prefix'?'prefix':p.role==='suffix'?'suffix':''}" ${action}><b>${esc(p.text)}</b>${p.meaning?`<small>${esc(p.meaning)}</small>`:''}</${action?'button':'span'}>`;}
export function morphologyHTML(w,lib){
  const units=w.construction?.parts||w.parts;
  const html=units.map((p,i)=>`${i?'<i class="morph-plus">+</i>':''}${w.construction?.groupStart===i?'<i class="morph-bracket">[</i>':''}${partHTML(p,lib,w)}${w.construction?.groupEnd===i?'<i class="morph-bracket">]</i>':''}`).join('');
  const title=w.morphologyKind==='historical'?'词源与词形线索':w.morphologyKind==='transparent'?'沿着构词理解含义':'构词与词源线索';return`<section class="word-section morphology-section"><div class="section-heading"><h2>${title}</h2><span>点击词根词缀查看知识卡</span></div><div class="morph-formula">${html}</div><p class="morph-explanation">${esc(w.explanation)}</p>${w.teachingSteps?.length?`<ol class="teaching-steps">${w.teachingSteps.map(step=>`<li><strong lang="en">${esc(step.form)}</strong><span>${esc(step.meaning)}</span>${step.note?`<small>${esc(step.note)}</small>`:''}</li>`).join('')}</ol>`:''}</section>`;
}
function pathFor(w,f){const root='root:'+f.id,id=canonicalId(w.id),path=[id],seen=new Set(path);let curr=id;for(let i=0;i<f.wordIds.length+1;i++){const edge=f.edges.find(e=>e.to===curr);if(!edge||seen.has(edge.from))break;path.unshift(edge.from);seen.add(edge.from);curr=edge.from;if(curr===root)break;}return path;}
function familyMini(w,f,lib){const path=pathFor(w,f);return`<div class="word-mini-map">${path.map((id,i)=>{const root=id.startsWith('root:'),obj=root?f:lib.words[id],edge=i?f.edges.find(e=>e.from===path[i-1]&&e.to===id):null;return`${i?`<div class="mini-map-link ${edge?.type==='origin'?'historical':''}"><span>${esc(edge?.type==='origin'?'历史同源':edge?.label?.split('：')[0]||'词形联系')}</span></div>`:''}<button class="mini-map-node ${id===canonicalId(w.id)?'current':''}" ${root?`data-card="root-${f.id}"`:`data-word="${esc(id)}"`}><strong>${esc(root?obj.label:obj.word)}</strong><small>${esc(root?obj.meaning:obj.meaning.split('；')[0])}</small></button>`;}).join('')}</div>`;}
function relations(w){const synonyms=w.synonymsDetailed||(w.synonyms||[]).map(word=>typeof word==='string'?{word}:word),antonyms=w.antonymsDetailed||(w.antonyms||[]).map(word=>typeof word==='string'?{word}:word);return`<section class="word-section word-relations"><div><h2>近义表达 · 对照理解</h2>${synonyms.length?synonyms.map(x=>`<div class="relation-item"><strong lang="en">${esc(x.word)}</strong>${x.meaning?`<span>${esc(x.meaning)}</span>`:''}${x.usage?`<p>${esc(x.usage)}</p>`:''}</div>`).join(''):'<p class="muted">这个义项没有适合直接替换的近义词。</p>'}</div><div><h2>反义表达 · 沿词回忆</h2>${antonyms.length?antonyms.map(x=>`<div class="relation-item"><strong lang="en">${esc(x.word)}</strong>${x.meaning?`<span>${esc(x.meaning)}</span>`:''}${x.usage?`<p>${esc(x.usage)}</p>`:''}</div>`).join(''):'<p class="muted">这个义项没有合适的直接反义词。</p>'}</div></section>`;}
export function renderWordCard(id,lib,state,{back='families'}={}){
  const w=studyItem(lib,id);if(!w)return'<div class="empty"><h2>没有找到这个词条</h2><a href="#families">返回词族</a></div>';
  const backFamily=back.startsWith('family/')?back.slice(7):'',f=lib.families.find(f=>f.id===(w.families.includes(backFamily)?backFamily:w.families[0])),p=state.words[id],m=state.meanings?.[id],locked=state.session||state.meaningSession?.queue.length,status=p?.status==='known'||foundationSkipped(state,w)?'known':eligible(state,lib,id)?m||p?.status==='review'?((m?.due??Infinity)<=Date.now()||(p?.status==='review'&&p.due<=Date.now())?'due':'review'):'new':'outside',date=x=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'short',day:'numeric'}).format(x),statusLabel={known:'已掌握',due:'今天待复习',review:'复习中',new:'尚未学习',outside:'关联词'},examples=w.examples?.length?w.examples:[{text:w.example,translation:w.translation}],bookmarked=state.bookmarks.includes(id),pending=state.pending.includes(id),extra=(lib.words[w.wordId||id]?.studyItemIds||[]).filter(x=>x!==id);
  return`<div class="word-page"><div class="word-breadcrumb"><div><a href="#families">词族图谱</a><span>/</span><a href="#family/${f.id}">${esc(f.label)} 词族</a><span>/</span><b>${esc(w.word)}</b>${w.isAdditionalSense?'<span class="tag">拓展义项</span>':''}</div><a class="back-to-map" href="#${esc(back)}">${back==='practice'?'回到当前练习':back.startsWith('browse')?'返回浏览':back.startsWith('read')?'返回刷词':'返回词族图谱'}</a></div><div class="word-workspace"><article class="rich-word-card"><section class="word-hero"><div class="row between"><div class="row"><span class="tag">${esc(f.label)} 词族</span>${w.targets?.includes('cet4')?'<span class="tag">四级词目</span>':w.targets?.includes('cet6')?'<span class="tag">六级增量</span>':`<span class="tag">${w.isAdditionalSense?'拓展义项':'暂未分级'}</span>`}<span class="word-status-label">${esc(statusLabel[status])}</span></div><button class="word-save" data-action="bookmark" data-id="${esc(id)}" aria-pressed="${bookmarked}" aria-label="${bookmarked?'取消收藏':'收藏这个词'}">${bookmarked?'★':'☆'}</button></div><div class="word-title-row"><h1 lang="en">${esc(w.word)}</h1><div class="row"><button class="btn small outline" data-action="speak" data-id="${esc(id)}" data-accent="en-GB">${needsContextAudio(w,lib)?'英音例句':'英音'}</button><button class="btn small outline" data-action="speak" data-id="${esc(id)}" data-accent="en-US">${needsContextAudio(w,lib)?'美音例句':'美音'}</button></div></div>${needsContextAudio(w,lib)?'<p class="target-note">这里播放完整例句，帮助听清这个词在当前义项中的用法。</p>':''}${w.ipa?.uk?`<div class="ipa" lang="en">英 ${esc(w.ipa.uk)}${w.ipa.us&&w.ipa.us!==w.ipa.uk?`　美 ${esc(w.ipa.us)}`:''}</div>`:''}<div class="word-definition"><span class="tag">${esc(w.pos)}</span><p>${esc(w.meaning)}</p></div>${w.targetNote?`<p class="target-note">${esc(w.targetNote)}</p>`:''}</section>${morphologyHTML(w,lib)}<section class="word-section word-clues"><div><h2>词性线索</h2><p>${esc(w.posHint||w.construction?.posHint||'结合词缀、单词形式与句子中的位置判断词性。')}</p>${w.morphologyKind==='historical'||w.morphologyKind==='mixed'?'<small>历史同源与现代构词分别理解，词根联想不能代替真实词义。</small>':''}</div><div><h2>记忆联想 <span class="tag">帮助记忆</span></h2><p>${esc(w.mnemonic)}</p></div></section><section class="word-section word-examples"><div class="section-heading"><h2>放进语境里记忆</h2><span>原创学习例句</span></div>${examples.map((e,i)=>`<div class="word-example"><span class="example-number">${i+1}</span><div><p lang="en">${esc(e.text)}</p><p class="muted">${esc(e.translation)}</p></div><button data-action="speak-example" data-id="${esc(id)}" data-index="${i}" aria-label="朗读第${i+1}条例句">◖))</button></div>`).join('')}<div class="word-collocations"><span>常见搭配</span>${[...new Set([w.collocation,...(w.collocations||[])].filter(Boolean))].map(x=>`<span lang="en">${esc(x)}</span>`).join('')}</div></section>${relations(w)}${w.otherSenses?.length||extra.some(x=>x.includes('::'))?`<section class="word-section"><h2>其他用法与拓展义项</h2>${w.otherSenses?.map(x=>`<p class="other-sense"><span class="tag">${esc(x.pos)}</span> ${esc(x.meaning)}</p>`).join('')||''}${extra.filter(x=>x.includes('::')).map(x=>{const sense=studyItem(lib,x);return`<button class="extra-sense-card" data-word="${esc(x)}"><strong>${esc(sense.pos)} ${esc(sense.meaning)}</strong><span>基础词的新用法 · 单独学习与复习</span></button>`;}).join('')}</section>`:''}<footer class="word-card-actions"><button class="btn" data-action="pending" data-id="${esc(id)}">${pending?'移出待学':'加入待学'}</button><button class="btn outline" data-action="word-known" data-id="${esc(id)}" ${locked?'disabled':''}>${p?.status==='known'?'重新学习这个义项':'这个义项我已掌握'}</button><span>${locked?'完成本轮后可调整掌握状态':'理解构词后，再用例句确认词义'}</span></footer></article><aside class="word-sidebar"><section class="card"><div class="section-heading"><h2>它在词族中的位置</h2><a href="#family/${f.id}">完整词族</a></div><p class="muted">先找到联系，再记住这个词。</p>${w.families.length>1?`<div class="row family-memberships">${w.families.map(fid=>`<a class="tag" href="#family/${fid}">${esc(lib.families.find(x=>x.id===fid).label)}</a>`).join('')}</div>`:''}${familyMini(w,f,lib)}</section><section class="card word-history"><h2>词根与词源线索</h2><p>${esc(w.etymologyNote||f.description)}</p>${sourceLink(w.etymologySource||w.source,'词源参考')}</section><section class="card"><h2>我的学习状态</h2><dl class="word-state"><dt>当前状态</dt><dd>${esc(statusLabel[status])}</dd><dt>词义回忆</dt><dd>${p?.status==='known'||foundationSkipped(state,w)?'当前已跳过':m?date(m.due)+'复习':'首次评分后安排'}</dd><dt>拼写巩固</dt><dd>${p?.status==='review'?date(p.due)+'复习':p?.status==='known'?'当前已跳过':'尚未参加拼写练习'}</dd></dl><p class="notice">按词族组织复习，为每个义项分别安排进度。</p></section><section class="card word-sources"><h2>内容参考</h2><div class="row">${sourceLink(w.meaningSource,'词义与用法')}${sourceLink(w.etymologySource||w.source,'词源与构词')}${w.targetEvidence?.[0]?.url?sourceLink(w.targetEvidence[0].url,'考试词目来源'):''}</div><small>词缀提供线索，具体含义以语境和真实用法为准。语音由设备朗读。</small></section></aside></div></div>`;
}
